            for x in v.values():
                p = pos(x)
                if p is not None:
                    out.append(p)
        elif isinstance(v, (list, tuple)):
            for x in v:
                p = pos(x)
                if p is not None:
                    out.append(p)
        return out

    s = pos(o.get("self_position")) or [0, 0]
    p = pos(o.get("opponent_position"))
    rs = cells(o.get("resources"))
    obs = {tuple(x) for x in cells(o.get("obstacles"))}
