        return (w <= 0 or 0 <= x < w) and (h <= 0 or 0 <= y < h) and (x, y) not in obs

    if rs:
        t = min(rs, key=lambda a: abs(a[0] - s[0]) + abs(a[1] - s[1]))
    else:
        t = None

    best = None
    bestv = -10**9
    for dx, dy in dirs:
        x, y = s[0] + dx, s[1] + dy
        if not ok(x, y):
            continue
        v = 0
        if t is not None:
            v -= abs(x - t[0]) + abs(y - t[1]) * 3
        if p is not None:
            v += abs(x - p[0]) + abs(y - p[1])
        if (x, y) in sp:
